import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  /* config options here */
};

export default nextConfig;

'use client';

import { motion } from "framer-motion";
import { Check, Zap, Shield, Users, MessageCircle, Code2, Crown, Rocket } from "lucide-react";
import Navigation from "@/components/Navigation";
import Footer from "@/components/Footer";

export default function Pricing() {
  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
      <Navigation />

      {/* Hero Section */}
      <section className="relative px-6 pt-20 pb-32">
        <div className="max-w-7xl mx-auto text-center">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8 }}
          >
            <h1 className="text-6xl md:text-7xl font-bold text-white mb-6">
              Simple, Transparent
              <span className="block bg-gradient-to-r from-blue-400 to-purple-500 bg-clip-text text-transparent">
                Pricing
              </span>
            </h1>
          </motion.div>

          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, delay: 0.2 }}
            className="text-xl md:text-2xl text-gray-300 mb-12 max-w-4xl mx-auto"
          >
            Scale from prototype to production with pricing that grows with your success. 
            Start free, upgrade anytime, and never pay for what you don&apos;t use.
          </motion.p>
        </div>
      </section>

      {/* Pricing Cards */}
      <section className="py-16 bg-gradient-to-b from-slate-900 to-gray-900">
        <div className="max-w-7xl mx-auto px-6">
          <div className="grid md:grid-cols-3 gap-8 max-w-6xl mx-auto">
            {[
              {
                name: "Starter",
                price: "Free",
                description: "Perfect for experimentation and small projects",
                features: [
                  "10,000 tokens/month",
                  "Basic models access",
                  "Community support",
                  "API access",
                  "Basic analytics",
                  "Rate limiting: 60 RPM"
                ],
                cta: "Get Started",
                popular: false,
                icon: <Zap className="w-6 h-6" />
              },
              {
                name: "Professional",
                price: "$99",
                period: "/month",
                description: "Ideal for growing teams and production apps",
                features: [
                  "1M tokens/month",
                  "All models + custom fine-tuning",
                  "Priority support",
                  "Advanced analytics",
                  "Team collaboration",
                  "99.9% uptime SLA",
                  "Rate limiting: 1000 RPM",
                  "Custom integrations"
                ],
                cta: "Start Free Trial",
                popular: true,
                icon: <Rocket className="w-6 h-6" />
              },
              {
                name: "Enterprise",
                price: "Custom",
                description: "For large-scale deployments and custom needs",
                features: [
                  "Unlimited tokens",
                  "Dedicated infrastructure",
                  "24/7 support",
                  "Custom integrations",
                  "Advanced security",
                  "Success manager",
                  "Custom rate limits",
                  "On-premise deployment",
                  "Custom model training"
                ],
                cta: "Contact Sales",
                popular: false,
                icon: <Crown className="w-6 h-6" />
              }
            ].map((plan, index) => (
              <motion.div
                key={index}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6, delay: index * 0.1 }}
                viewport={{ once: true }}
                className={`relative p-8 rounded-2xl border transition-all hover:transform hover:scale-105 ${
                  plan.popular 
                    ? 'bg-gradient-to-b from-blue-900/50 to-purple-900/50 border-blue-500 shadow-2xl shadow-blue-500/20' 
                    : 'bg-gray-800/50 border-gray-700 hover:border-gray-600'
                }`}
              >
                {plan.popular && (
                  <div className="absolute -top-4 left-1/2 transform -translate-x-1/2">
                    <span className="bg-gradient-to-r from-blue-500 to-purple-600 text-white px-4 py-2 rounded-full text-sm font-medium">
                      Most Popular
                    </span>
                  </div>
                )}

                <div className="text-center mb-8">
                  <div className="flex items-center justify-center mb-4">
                    <div className={`p-3 rounded-full ${plan.popular ? 'bg-blue-500/20' : 'bg-gray-700/50'}`}>
                      {plan.icon}
                    </div>
                  </div>
                  <h3 className="text-2xl font-bold text-white mb-2">{plan.name}</h3>
                  <div className="mb-4">
                    <span className="text-4xl font-bold text-white">{plan.price}</span>
                    {plan.period && <span className="text-gray-400">{plan.period}</span>}
                  </div>
                  <p className="text-gray-400">{plan.description}</p>
                </div>

                <ul className="space-y-4 mb-8">
                  {plan.features.map((feature, featureIndex) => (
                    <li key={featureIndex} className="flex items-center text-gray-300">
                      <Check className="w-5 h-5 text-green-500 mr-3 flex-shrink-0" />
                      <span>{feature}</span>
                    </li>
                  ))}
                </ul>

                <button className={`w-full py-3 rounded-full font-semibold transition-colors ${
                  plan.popular
                    ? 'bg-gradient-to-r from-blue-600 to-purple-600 text-white hover:from-blue-700 hover:to-purple-700'
                    : 'bg-gray-700 text-white hover:bg-gray-600'
                }`}>
                  {plan.cta}
                </button>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Add-ons */}
      <section className="py-24 bg-gradient-to-b from-gray-900 to-slate-900">
        <div className="max-w-7xl mx-auto px-6">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8 }}
            viewport={{ once: true }}
            className="text-center mb-16"
          >
            <h2 className="text-5xl font-bold text-white mb-6">
              Powerful
              <span className="block bg-gradient-to-r from-blue-400 to-purple-500 bg-clip-text text-transparent">
                Add-ons
              </span>
            </h2>
            <p className="text-xl text-gray-300 max-w-3xl mx-auto">
              Enhance your plan with additional features and capabilities as your needs grow.
            </p>
          </motion.div>

          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
            {[
              {
                icon: <Shield className="w-8 h-8 text-green-500" />,
                name: "Advanced Security",
                price: "$49/month",
                description: "SOC2 compliance, advanced encryption, and audit logs",
                features: ["End-to-end encryption", "Audit logging", "SOC2 compliance", "Advanced access controls"]
              },
              {
                icon: <Users className="w-8 h-8 text-blue-500" />,
                name: "Team Management",
                price: "$29/month",
                description: "Advanced team collaboration and permission management",
                features: ["Role-based access", "Team analytics", "Shared workspaces", "Usage reporting"]
              },
              {
                icon: <MessageCircle className="w-8 h-8 text-purple-500" />,
                name: "Priority Support",
                price: "$199/month",
                description: "Dedicated support channel with faster response times",
                features: ["1-hour response SLA", "Dedicated support engineer", "Phone support", "Priority bug fixes"]
              }
            ].map((addon, index) => (
              <motion.div
                key={index}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6, delay: index * 0.1 }}
                viewport={{ once: true }}
                className="bg-gray-800/50 rounded-2xl p-6 border border-gray-700 hover:border-gray-600 transition-all"
              >
                <div className="flex items-center mb-4">
                  <div className="p-2 bg-gray-700/50 rounded-lg mr-4">
                    {addon.icon}
                  </div>
                  <div>
                    <h3 className="text-lg font-semibold text-white">{addon.name}</h3>
                    <div className="text-blue-400 font-medium">{addon.price}</div>
                  </div>
                </div>
                <p className="text-gray-400 mb-4">{addon.description}</p>
                <ul className="space-y-2">
                  {addon.features.map((feature, featureIndex) => (
                    <li key={featureIndex} className="flex items-center text-sm text-gray-300">
                      <Check className="w-4 h-4 text-green-500 mr-2 flex-shrink-0" />
                      <span>{feature}</span>
                    </li>
                  ))}
                </ul>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* FAQ */}
      <section className="py-24 bg-gradient-to-b from-slate-900 to-gray-900">
        <div className="max-w-4xl mx-auto px-6">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8 }}
            viewport={{ once: true }}
            className="text-center mb-16"
          >
            <h2 className="text-5xl font-bold text-white mb-6">
              Frequently Asked
              <span className="block bg-gradient-to-r from-blue-400 to-purple-500 bg-clip-text text-transparent">
                Questions
              </span>
            </h2>
          </motion.div>

          <div className="space-y-6">
            {[
              {
                q: "What happens if I exceed my token limit?",
                a: "We'll notify you when you approach your limit. You can upgrade your plan or purchase additional tokens. We won't cut off your service abruptly."
              },
              {
                q: "Can I change my plan anytime?",
                a: "Yes, you can upgrade or downgrade your plan at any time. Changes take effect immediately, and you'll be billed pro-rata for the current month."
              },
              {
                q: "Do you offer annual discounts?",
                a: "Yes! Annual subscriptions receive a 20% discount. Enterprise customers can discuss custom pricing with our sales team."
              },
              {
                q: "What's included in the free tier?",
                a: "The free tier includes 10,000 tokens per month, access to our basic models, community support, and standard API access."
              },
              {
                q: "How do you ensure data privacy?",
                a: "We never store your data. All requests are processed in real-time and immediately discarded. We're SOC2 Type II compliant with enterprise-grade security."
              },
              {
                q: "Can I get a custom enterprise solution?",
                a: "Absolutely! Our enterprise team can work with you to create custom solutions including on-premise deployment, dedicated infrastructure, and custom model training."
              }
            ].map((faq, index) => (
              <motion.div
                key={index}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6, delay: index * 0.1 }}
                viewport={{ once: true }}
                className="bg-gray-800/50 rounded-2xl p-6 border border-gray-700"
              >
                <h3 className="text-lg font-semibold text-white mb-3">{faq.q}</h3>
                <p className="text-gray-400">{faq.a}</p>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* CTA */}
      <section className="py-24 bg-gradient-to-b from-gray-900 to-slate-900">
        <div className="max-w-4xl mx-auto px-6 text-center">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8 }}
            viewport={{ once: true }}
          >
            <h2 className="text-5xl font-bold text-white mb-6">
              Ready to Get
              <span className="block bg-gradient-to-r from-blue-400 to-purple-500 bg-clip-text text-transparent">
                Started?
              </span>
            </h2>
            <p className="text-xl text-gray-300 mb-12 max-w-2xl mx-auto">
              Join thousands of developers building the future with our foundation models. 
              Start free, no credit card required.
            </p>

            <div className="flex flex-col sm:flex-row items-center justify-center space-y-4 sm:space-y-0 sm:space-x-6">
              <button className="group px-8 py-4 bg-gradient-to-r from-blue-600 to-purple-600 text-white text-lg font-semibold rounded-full hover:from-blue-700 hover:to-purple-700 transition-all transform hover:scale-105 shadow-2xl">
                Start Free Trial
              </button>
              <button className="px-8 py-4 border-2 border-gray-600 text-white text-lg font-semibold rounded-full hover:border-white transition-colors">
                Contact Sales
              </button>
            </div>

            <p className="text-gray-500 text-sm mt-6">
              No credit card required • Cancel anytime • 30-day money-back guarantee
            </p>
          </motion.div>
        </div>
      </section>

      <Footer />
    </div>
  );
}

