import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: {
    template: '%s - NeuraLLM',
    default: 'NeuraLLM - Advanced Foundation Models for Modern AI'
  },
  description: 'Deploy state-of-the-art Large Language Models with enterprise-grade security, lightning-fast performance, and unprecedented customization capabilities.',
  keywords: 'AI API, foundation models, LLM, machine learning, artificial intelligence, API development, AI tools',
  authors: [{ name: 'NeuraLLM' }],
  creator: 'NeuraLLM',
  publisher: 'NeuraLLM',
  formatDetection: {
    email: false,
    address: false,
    telephone: false,
  },
  metadataBase: new URL('https://neurallm.com'),
  openGraph: {
    type: 'website',
    locale: 'en_US',
    url: 'https://neurallm.com',
    title: 'NeuraLLM - Advanced Foundation Models for Modern AI',
    description: 'Deploy state-of-the-art Large Language Models with enterprise-grade security, lightning-fast performance, and unprecedented customization capabilities.',
    siteName: 'NeuraLLM',
  },
  twitter: {
    card: 'summary_large_image',
    title: 'NeuraLLM - Advanced Foundation Models for Modern AI',
    description: 'Deploy state-of-the-art Large Language Models with enterprise-grade security, lightning-fast performance, and unprecedented customization capabilities.',
    creator: '@neurallm',
  },
  robots: {
    index: true,
    follow: true,
    googleBot: {
      index: true,
      follow: true,
      'max-video-preview': -1,
      'max-image-preview': 'large',
      'max-snippet': -1,
    },
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <body
        className={`${geistSans.variable} ${geistMono.variable} antialiased`}
      >
        {children}
      </body>
    </html>
  );
}

'use client';

import Link from "next/link";
import { motion } from "framer-motion";
import { Brain } from "lucide-react";

export default function Navigation() {
  return (
    <nav className="relative z-50 px-6 py-4">
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.6 }}
          className="flex items-center space-x-2"
        >
          <Link href="/" className="flex items-center space-x-2">
            <div className="w-8 h-8 bg-gradient-to-r from-blue-500 to-purple-600 rounded-lg flex items-center justify-center">
              <Brain className="w-5 h-5 text-white" />
            </div>
            <span className="text-xl font-bold text-white">NeuraLLM</span>
          </Link>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
          className="hidden md:flex items-center space-x-8"
        >
          <Link href="/#features" className="text-gray-300 hover:text-white transition-colors">Features</Link>
          <Link href="/pricing" className="text-gray-300 hover:text-white transition-colors">Pricing</Link>
          <Link href="/about" className="text-gray-300 hover:text-white transition-colors">About</Link>
          <Link href="/#contact" className="text-gray-300 hover:text-white transition-colors">Contact</Link>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.6, delay: 0.4 }}
          className="flex items-center space-x-4"
        >
          <Link 
            href="/signin" 
            className="px-4 py-2 text-gray-300 hover:text-white transition-colors"
          >
            Sign In
          </Link>
          <Link 
            href="/get-started"
            className="px-6 py-2 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-full font-medium hover:from-blue-700 hover:to-purple-700 transition-colors"
          >
            Get Started
          </Link>
        </motion.div>
      </div>
    </nav>
  );
}

