import { render, screen, fireEvent } from '@testing-library/react';
import Home from '@/app/page';

jest.mock('framer-motion', () => ({
  motion: {
    div: ({ children, whileInView, viewport, ...props }: any) => <div {...props}>{children}</div>,
    nav: ({ children, ...props }: any) => <nav {...props}>{children}</nav>,
    section: ({ children, ...props }: any) => <section {...props}>{children}</section>,
    footer: ({ children, ...props }: any) => <footer {...props}>{children}</footer>,
    h1: ({ children, ...props }: any) => <h1 {...props}>{children}</h1>,
    h2: ({ children, ...props }: any) => <h2 {...props}>{children}</h2>,
    h3: ({ children, ...props }: any) => <h3 {...props}>{children}</h3>,
    p: ({ children, ...props }: any) => <p {...props}>{children}</p>,
  }
}));

describe('Home Page', () => {
  beforeEach(() => {
    render(<Home />);
  });

  test('renders the main heading', () => {
    const heading = screen.getByText('The Future of');
    expect(heading).toBeInTheDocument();

    const subHeading = screen.getByText('Foundation Models');
    expect(subHeading).toBeInTheDocument();
  });

  test('renders the company logo and name', () => {
    const companyName = screen.getAllByText('NeuraLLM');
    expect(companyName).toHaveLength(2); // Header and Footer
  });

  test('renders navigation links', () => {
    // Use more specific queries to avoid duplicates
    const navSection = screen.getByRole('navigation');
    expect(navSection).toBeInTheDocument();

    // Check that navigation contains the expected links
    const featuresLink = screen.getByRole('link', { name: 'Features' });
    expect(featuresLink).toHaveAttribute('href', '/#features');
  });

  test('renders CTA buttons', () => {
    const startButtons = screen.getAllByRole('button', { name: /start free trial/i });
    expect(startButtons.length).toBeGreaterThan(0);

    expect(screen.getByRole('button', { name: /watch demo/i })).toBeInTheDocument();

    const getStartedLinks = screen.getAllByText('Get Started');
    expect(getStartedLinks.length).toBeGreaterThan(0);
  });

  test('renders features section', () => {
    expect(screen.getByText('Lightning Fast')).toBeInTheDocument();
    expect(screen.getByText('Enterprise Security')).toBeInTheDocument();
    expect(screen.getByText('Custom Models')).toBeInTheDocument();
    expect(screen.getByText('Real-time Analytics')).toBeInTheDocument();
    expect(screen.getByText('Team Collaboration')).toBeInTheDocument();
    expect(screen.getByText('Developer First')).toBeInTheDocument();
  });

  test('renders pricing preview section', () => {
    expect(screen.getByText('Start Building')).toBeInTheDocument();
    expect(screen.getByText('Today')).toBeInTheDocument();
    expect(screen.getByText('View All Plans')).toBeInTheDocument();
    expect(screen.getByText('Free tier includes 10,000 tokens/month • No credit card required')).toBeInTheDocument();
  });

  test('renders contact form', () => {
    expect(screen.getByPlaceholderText('Your name')).toBeInTheDocument();
    expect(screen.getByPlaceholderText('your@email.com')).toBeInTheDocument();
    expect(screen.getByPlaceholderText('Tell us about your project...')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /send message/i })).toBeInTheDocument();
  });

  test('renders footer with copyright', () => {
    expect(screen.getByText('© 2024 NeuraLLM Inc. All rights reserved.')).toBeInTheDocument();
    expect(screen.getByText('Privacy')).toBeInTheDocument();
    expect(screen.getByText('Terms')).toBeInTheDocument();
    expect(screen.getByText('Status')).toBeInTheDocument();
  });

  test('renders API code example', () => {
    expect(screen.getByText(/curl -X POST https:\/\/api\.neurallm\.com/)).toBeInTheDocument();
    expect(screen.getByText(/Authorization: Bearer YOUR_API_KEY/)).toBeInTheDocument();
  });

  test('contact form inputs work correctly', () => {
    const nameInput = screen.getByPlaceholderText('Your name') as HTMLInputElement;
    const emailInput = screen.getByPlaceholderText('your@email.com') as HTMLInputElement;
    const messageInput = screen.getByPlaceholderText('Tell us about your project...') as HTMLTextAreaElement;

    fireEvent.change(nameInput, { target: { value: 'John Doe' } });
    fireEvent.change(emailInput, { target: { value: 'john@example.com' } });
    fireEvent.change(messageInput, { target: { value: 'Test message' } });

    expect(nameInput.value).toBe('John Doe');
    expect(emailInput.value).toBe('john@example.com');
    expect(messageInput.value).toBe('Test message');
  });


  test('renders feature statistics', () => {
    expect(screen.getByText('~50ms avg latency')).toBeInTheDocument();
    expect(screen.getByText('99.99% uptime SLA')).toBeInTheDocument();
    expect(screen.getByText('500B+ parameters')).toBeInTheDocument();
    expect(screen.getByText('10+ SDKs available')).toBeInTheDocument();
  });
});

