    expect(pricingElements.length).toBeGreaterThan(0);
  });

  test('renders pricing plans', () => {
    expect(screen.getByText('Starter')).toBeInTheDocument();
    expect(screen.getByText('Professional')).toBeInTheDocument();

    const enterpriseElements = screen.getAllByText('Enterprise');
    expect(enterpriseElements.length).toBeGreaterThan(0);

    expect(screen.getByText('Free')).toBeInTheDocument();
    expect(screen.getByText('$99')).toBeInTheDocument();
    expect(screen.getByText('Custom')).toBeInTheDocument();
  });

  test('renders plan features', () => {
    expect(screen.getByText('10,000 tokens/month')).toBeInTheDocument();
    expect(screen.getByText('1M tokens/month')).toBeInTheDocument();
    expect(screen.getByText('Unlimited tokens')).toBeInTheDocument();
    expect(screen.getByText('Basic models access')).toBeInTheDocument();
    expect(screen.getByText('Priority support')).toBeInTheDocument();
    expect(screen.getByText('Dedicated infrastructure')).toBeInTheDocument();
  });

  test('renders CTA buttons', () => {
    const getStartedButtons = screen.getAllByText('Get Started');
    expect(getStartedButtons.length).toBeGreaterThan(0);

    const startFreeTrialButtons = screen.getAllByText('Start Free Trial');
    expect(startFreeTrialButtons.length).toBeGreaterThan(0);

    const contactSalesButtons = screen.getAllByText('Contact Sales');
