    expect(screen.getByText('Powerful')).toBeInTheDocument();
    expect(screen.getByText('Add-ons')).toBeInTheDocument();
    expect(screen.getByText('Advanced Security')).toBeInTheDocument();
    expect(screen.getByText('Team Management')).toBeInTheDocument();
    expect(screen.getByText('Priority Support')).toBeInTheDocument();
  });

  test('renders FAQ section', () => {
    expect(screen.getByText('Frequently Asked')).toBeInTheDocument();
    expect(screen.getByText('Questions')).toBeInTheDocument();
    expect(screen.getByText('What happens if I exceed my token limit?')).toBeInTheDocument();
    expect(screen.getByText('Can I change my plan anytime?')).toBeInTheDocument();
    expect(screen.getByText('Do you offer annual discounts?')).toBeInTheDocument();
  });

  test('renders final CTA section', () => {
    expect(screen.getByText('Ready to Get')).toBeInTheDocument();
    expect(screen.getByText('Started?')).toBeInTheDocument();
    expect(screen.getByText('No credit card required • Cancel anytime • 30-day money-back guarantee')).toBeInTheDocument();
  });

  test('renders navigation', () => {
    const companyName = screen.getAllByText('NeuraLLM');
    expect(companyName.length).toBeGreaterThan(0);
  });

  test('renders footer', () => {
    expect(screen.getByText('© 2024 NeuraLLM Inc. All rights reserved.')).toBeInTheDocument();
  });
});

